/** 
 * Creates a  {@code Builder} of a {@link BloomFilter BloomFilter<T>}, with the expected number of insertions and expected false positive probability. <p>Note that overflowing a  {@code BloomFilter} with significantly more elementsthan specified, will result in its saturation, and a sharp deterioration of its false positive probability. <p>The constructed  {@code BloomFilter<T>} will be serializable if the provided{@code Funnel<T>} is.<p>It is recommended the funnel is implemented as a Java enum. This has the benefit of ensuring proper serialization and deserialization, which is important since  {@link #equals} also relieson object identity of funnels.
 * @param funnel the funnel of T's that the constructed {@code BloomFilter<T>} will use
 * @param expectedInsertions the number of expected insertions to the constructed{@code BloomFilter<T>}; must be positive
 * @param fpp the desired false positive probability (must be positive and less than 1.0)
 * @return a {@code BloomFilter}
 */
public static <T>BloomFilter<T> create(Funnel<T> funnel,int expectedInsertions,double fpp){
  checkNotNull(funnel);
  checkArgument(expectedInsertions >= 0,"Expected insertions (%s) cannot be negative",expectedInsertions);
  checkArgument(fpp > 0.0 & fpp < 1.0,"False positive probability (%s) must be in (0.0, 1.0)",fpp);
  if (expectedInsertions == 0) {
    expectedInsertions=1;
  }
  int numBits=optimalNumOfBits(expectedInsertions,fpp);
  int numHashFunctions=optimalNumOfHashFunctions(expectedInsertions,numBits);
  return new BloomFilter<T>(new BitArray(numBits),numHashFunctions,funnel,BloomFilterStrategies.MURMUR128_MITZ_32);
}
